const allItems = $input.all();
const extractItems = $('🔍 Extraire les PDFs').all();
const results = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i];
  const src = extractItems[i] || { json: {}, binary: {} };

  let isFacture = false;
  let isAvoir = false;
  let emiseParClimatPro = false;
  let fournisseur = 'Inconnu';
  let client = '';
  let objet = 'Facture';
  let montant = '0,00';
  let dateFacture = new Date().toISOString().split('T')[0];
  let numeroFacture = '';
  let raison = '';

  try {
    // Reponse Claude : content[] -> premier bloc de type text (content[0].text en pratique)
    const blocks = Array.isArray(item.json.content) ? item.json.content : [];
    const textBlock = blocks.find(b => b && b.type === 'text') || blocks[0] || {};
    const responseText = textBlock.text || '{}';
    let cleanText = responseText.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
    const a = cleanText.indexOf('{');
    const b = cleanText.lastIndexOf('}');
    if (a !== -1 && b > a) cleanText = cleanText.slice(a, b + 1);
    const data = JSON.parse(cleanText);

    isFacture = data.is_facture === true;
    isAvoir = data.is_avoir === true;
    emiseParClimatPro = data.emise_par_climatpro === true;
    raison = data.raison || '';

    if (isFacture || isAvoir) {
      if (data.fournisseur && data.fournisseur !== null) fournisseur = data.fournisseur;
      if (data.client && data.client !== null) client = data.client;
      if (data.objet && data.objet !== null) objet = data.objet;
      if (data.montant_ttc && data.montant_ttc !== null) montant = String(data.montant_ttc).replace('.', ',');
      if (data.date_facture && data.date_facture !== null) dateFacture = data.date_facture;
      if (data.numero_facture && data.numero_facture !== null) numeroFacture = String(data.numero_facture).trim();
    }
  } catch (e) {
    raison = 'Erreur parsing Claude: ' + e.message;
  }

  // Garde-fou : un document emis par ClimatPro n'est JAMAIS une depense
  const fournisseurNorm = String(fournisseur).toLowerCase().replace(/[\s\-_.]/g, '');
  const numeroNorm = numeroFacture.toUpperCase();
  const isClimatPro = emiseParClimatPro
    || fournisseurNorm.includes('climatpro')
    || /^FA1\d{4}$/.test(numeroNorm);
  if (isClimatPro && (isFacture || isAvoir)) {
    isFacture = false;
    isAvoir = false;
    raison = 'REJET ClimatPro (document emis par ClimatPro) - ' + raison;
  }

  const clean = (str) => str
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[\\/:*?"<>|]/g, '-').replace(/\s+/g, '-')
    .replace(/-+/g, '-').replace(/^-|-$/g, '').substring(0, 50);

  let fileName = null;
  if (isAvoir) {
    fileName = 'AVOIR_' + clean(fournisseur) + '_' + clean(objet) + '_' + montant + 'EUR.pdf';
  } else if (isFacture) {
    fileName = clean(fournisseur) + '_' + clean(objet) + '_' + montant + 'EUR.pdf';
  }

  // Cle de dedoublonnage pour le Sheet : fournisseur + numero si connu, sinon email + piece jointe
  const gmailMessageId = src.json.gmailMessageId || '';
  const attachmentName = src.json.attachmentName || '';
  const cle = numeroFacture
    ? clean(fournisseur).toLowerCase() + '|' + numeroFacture
    : (gmailMessageId || 'noid') + '|' + (attachmentName || 'nofile');

  results.push({
    json: {
      is_facture: isFacture,
      is_avoir: isAvoir,
      emise_par_climatpro: isClimatPro,
      raison: raison,
      fournisseur: fournisseur,
      client: client,
      objet: objet,
      montant_ttc: montant,
      date_facture: dateFacture,
      numero_facture: numeroFacture,
      fileName: fileName,
      gmail_message_id: gmailMessageId,
      attachment_name: attachmentName,
      cle: cle
    },
    binary: src.binary,
    pairedItem: { item: i }
  });
}

return results;

