  '07': 'JUILLET', '08': 'AOUT', '09': 'SEPTEMBRE',
  '10': 'OCTOBRE', '11': 'NOVEMBRE', '12': 'DECEMBRE'
};

return $input.all().map((item, i) => {
  const dateFacture = item.json.date_facture || '';
  let folderName = 'DEPENSES NON-DATE';

  if (dateFacture && dateFacture.length >= 7) {
    const annee = dateFacture.substring(0, 4);
